#!/usr/bin/env python3
"""Generate the Swift side of appearance.chromeStyle from its one source,
schemas/settings/chrome-styles.json (the language-neutral style table).

Writes three files under Packages/macOS/CmuxNext/Sources:
  CmuxNextDesignTokens/ChromeStyle.swift                       the enum and what each style implies
  CmuxNextActions/Catalog/ChromeStyleActionCatalog.swift  one palette action per style
  CmuxNextSettings/ChromeStyleSetting+Choices.swift      the Settings picker titles

Usage: scripts/cmux-next/gen-chrome-styles.py [--check]
--check exits 1 when a generated file differs from what the table gives.
"""
import json, pathlib, sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
TABLE = ROOT / "schemas/settings/chrome-styles.json"
SOURCES = ROOT / "Packages/macOS/CmuxNext/Sources"
HEADER = "// GENERATED by scripts/cmux-next/gen-chrome-styles.py from schemas/settings/chrome-styles.json.\n// Edit the table, then run the script; never edit this file by hand.\n\n"
SEPARATIONS = {"none", "dividers", "borders", "cards"}
SURFACES = {"same", "separate"}


def fail(message):
    sys.exit(f"gen-chrome-styles: {message}")


def swift_string(text):
    return json.dumps(text, ensure_ascii=False)


def case_name(style):
    return "`default`" if style["actionName"] == "default" else style["actionName"]


def validate(doc):
    ids = [s["id"] for s in doc["styles"]]
    if len(set(ids)) != len(ids) or doc["default"] not in ids:
        fail("style ids must be unique and include the default")
    for style in doc["styles"]:
        for knob, value in style["implies"].items():
            if knob not in doc["knobs"]:
                fail(f"{style['id']}: unknown knob {knob}")
            kind = doc["knobs"][knob]["type"]
            ok = {"bool": isinstance(value, bool), "string": isinstance(value, str),
                  "number": isinstance(value, (int, float)) and not isinstance(value, bool)}[kind]
            if not ok:
                fail(f"{style['id']}: {knob} must be a {kind}")
        imp = style["implies"]
        if imp.get("layout.paneSeparation", "dividers") not in SEPARATIONS:
            fail(f"{style['id']}: bad layout.paneSeparation")
        if imp.get("appearance.sidebarSurface", "same") not in SURFACES:
            fail(f"{style['id']}: bad appearance.sidebarSurface")
        if ("chrome.mainPane.shadeDark" in imp) != ("chrome.mainPane.shadeLight" in imp):
            fail(f"{style['id']}: set both shades or neither")


def switch(doc, name, signature, value_of, doc_comment):
    lines = [f"    /// {doc_comment}", f"    public {signature} {{", "        switch self {"]
    for style in doc["styles"]:
        lines.append(f"        case .{case_name(style)}: {value_of(style)}")
    lines += ["        }", "    }"]
    return "\n".join(lines)


def optional(value, render):
    return "nil" if value is None else render(value)


def design(doc):
    num = lambda v: repr(float(v))
    cases = "\n".join(f"    case {case_name(s)}" + ("" if s["id"] == case_name(s).strip("`") else f" = {swift_string(s['id'])}")
                      for s in doc["styles"])
    summaries = "\n".join(f"/// - `{s['id']}`: {s['summary']}" for s in doc["styles"])
    parts = [
        switch(doc, "actionName", "var actionName: String", lambda s: swift_string(s["actionName"]),
               "The camel-case name in action ids (`appearance.chromeStyle.<name>`)."),
        switch(doc, "curved", "var curvedMainPane: Bool?",
               lambda s: optional(s["implies"].get("chrome.mainPane.curved"), lambda v: "true" if v else "false"),
               "Whether the workspace content is the curved main pane; nil keeps the tunable's default."),
        switch(doc, "separation", "var paneSeparation: PaneSeparation?",
               lambda s: optional(s["implies"].get("layout.paneSeparation"), lambda v: f"PaneSeparation.{v}"),
               "The pane separation when cmux.json sets none; nil keeps `Metrics.defaultPaneSeparation`'s rule."),
        switch(doc, "border", "var sidebarBorder: Bool?",
               lambda s: optional(s["implies"].get("sidebar.border"), lambda v: "true" if v else "false"),
               "The sidebar's edge line at rest when `sidebar.border` is unset; nil keeps it off."),
        switch(doc, "surface", "var sidebarSurface: SidebarSurface?",
               lambda s: optional(s["implies"].get("appearance.sidebarSurface"), lambda v: f"SidebarSurface.{v}"),
               "The sidebar surface when `appearance.sidebarSurface` is unset; nil keeps its default."),
        switch(doc, "step", "var borderlessStep: CGFloat?",
               lambda s: optional(s["implies"].get("chrome.mainPane.borderlessStep"), num),
               "Share of the separate shade a shared surface keeps with no line; nil keeps `SidebarSurface.borderlessStep`."),
        switch(doc, "floating", "var floatingPanes: Bool",
               lambda s: "true" if s["implies"].get("chrome.floatingPanes") else "false",
               "Every pane is its own unshaded card on the shaded chrome, with one even gap (`Metrics.floatingPanes`)."),
    ]
    shade_lines = ["    /// The separate surface's shade; nil keeps the tunable's default.",
                   "    public func separateShade(isDark: Bool) -> CGFloat? {", "        switch self {"]
    for s in doc["styles"]:
        imp = s["implies"]
        value = "nil" if "chrome.mainPane.shadeDark" not in imp else \
            f"isDark ? {num(imp['chrome.mainPane.shadeDark'])} : {num(imp['chrome.mainPane.shadeLight'])}"
        shade_lines.append(f"        case .{case_name(s)}: {value}")
    shade_lines += ["        }", "    }"]
    return (HEADER + "public import CoreGraphics\n\n"
            "/// `appearance.chromeStyle` in cmux.json: one easy string for the window's\n"
            "/// look. Each style supplies DEFAULTS for finer knobs; a key set in\n"
            "/// cmux.json wins, and a Debug Settings tunable wins over both.\n"
            f"{summaries}\n"
            "public nonisolated enum ChromeStyle: String, Sendable, CaseIterable, Codable {\n"
            f"{cases}\n\n" + "\n\n".join(parts) + "\n\n" + "\n".join(shade_lines) + "\n}\n")


def catalog(doc):
    rows = []
    for s in doc["styles"]:
        key = f"action.appearance.chromeStyle.{s['actionName']}"
        title = f"Window Style: {s['title']}"
        keywords = ", ".join(swift_string(k) for k in ["window", "style", "chrome", "appearance", "look"] + s["keywords"])
        rows.append(
            "            ActionDescriptor(\n"
            f"                id: {swift_string('appearance.chromeStyle.' + s['actionName'])},\n"
            f"                title: String(localized: {swift_string(key)}, defaultValue: {swift_string(title)}, table: \"SettingsActions\", bundle: .module),\n"
            f"                keywords: [{keywords}],\n"
            f"                category: .settings, symbol: {swift_string(s['symbol'])}, surfaces: [.palette],\n"
            f"                cliName: {swift_string('settings window-style-' + s['id'])},\n"
            "                surfacePlan: plan\n"
            "            ),")
    return (HEADER +
            "// One palette action per window style (`appearance.chromeStyle`), every\n"
            "// title starting with \"Window Style:\" so typing it lists them all. Settings\n"
            "// changes with no object: no context menu; MCP leaves them to the person.\n\n"
            "nonisolated enum ChromeStyleActionCatalog: ActionCatalogGroup {\n"
            "    static func descriptors() -> [ActionDescriptor] {\n"
            "        let plan = ActionSurfacePlan(cli: .offered, contextMenuExemption: .noObject, mcpExemption: .systemChange)\n"
            "        return [\n" + "\n".join(rows) + "\n        ]\n    }\n}\n")


def choices(doc):
    lines = []
    for s in doc["styles"]:
        key = f"settings.choice.chromeStyle.{s['actionName']}"
        lines.append(f"        case .{case_name(s)}: SettingsText.keyed({swift_string(key)}, {swift_string(s['title'])})")
    return (HEADER + "public import CmuxNextDesign\n\n"
            "extension ChromeStyleSetting {\n"
            "    /// The Settings picker title of `style`.\n"
            "    static func title(_ style: ChromeStyle) -> SettingText {\n"
            "        switch style {\n" + "\n".join(lines) + "\n        }\n    }\n}\n")


def main():
    check = "--check" in sys.argv[1:]
    doc = json.loads(TABLE.read_text())
    validate(doc)
    outputs = {
        SOURCES / "CmuxNextDesignTokens/ChromeStyle.swift": design(doc),
        SOURCES / "CmuxNextActions/Catalog/ChromeStyleActionCatalog.swift": catalog(doc),
        SOURCES / "CmuxNextSettings/ChromeStyleSetting+Choices.swift": choices(doc),
    }
    stale = [path for path, text in outputs.items() if not path.exists() or path.read_text() != text]
    if check:
        for path in stale:
            print(f"gen-chrome-styles: stale {path.relative_to(ROOT)}; run scripts/cmux-next/gen-chrome-styles.py", file=sys.stderr)
        sys.exit(1 if stale else 0)
    for path in stale:
        path.write_text(outputs[path])
        print(f"wrote {path.relative_to(ROOT)}")


main()
